  {
    "commit_sha": "d58988e4b18d60b5ae613fa75da60c8c8a8800f7",
    "category": "architecture",
    "title": "Overlapping I/O and CPU-bound work via background threading in retrieval pipeline",
    "body": "The system identified that LLM processing was the primary latency bottleneck (~5s) compared to embedding generation (~50ms). By moving embedding generation into a background thread, the pipeline now overlaps these operations, effectively hiding the fast embedding cost behind the slow LLM inference. This pattern is also applied to search queries where embedding generation runs concurrently with context setup.",
    "files": [
      "src/main.rs",
      "src/db.rs"
    ],
    "tags": "concurrency performance pipeline latency-optimization background-tasks"
  },
  {
    "commit_sha": "d58988e4b18d60b5ae613fa75da60c8c8a8800f7",
    "category": "pattern",
    "title": "Two-pass semantic search to minimize deserialization overhead",
    "body": "The original implementation loaded full database rows including JSON-serialized fields for all candidates before filtering by similarity. The optimized approach uses a two-pass strategy: first computing cosine similarity on raw embedding bytes and IDs, then fetching full row details only for the top-N results. This significantly reduces memory allocation and CPU time spent deserializing data that would ultimately be discarded.",
    "files": [
      "src/db.rs"
    ],
    "tags": "database-optimization semantic-search lazy-loading two-pass-algorithm"
  }
]

[
  {
    "commit_sha": "2a52ad7d0fa5217cc538b42e42a02cc969c39da8",
    "category": "pattern",
    "title": "Implementing idempotency in indexing pipelines via pre-checks",
    "body": "The commit introduces a mechanism to skip commits that already have insights, making the `diwa index` command idempotent. This architectural decision ensures that re-running the indexer fills gaps without duplicating data, which is crucial for robustness in automated or repeated CI/CD contexts.",
    "files": [
      "src/db.rs",
      "src/main.rs"
    ],
    "tags": "idempotency indexing database deduplication"
  },
  {
    "commit_sha": "2a52ad7d0fa5217cc538b42e42a02cc969c39da8",
    "category": "bugfix",
    "title": "Handling custom git hook paths to prevent stale installations",
    "body": "A bug was fixed where the tool failed to clean up hooks if `core.hooksPath` pointed to a different location (e.g., `.husky`) than the default `.git/hooks`. The fix ensures that when the active hook path differs from the installed location, the inactive hook is removed. This prevents stale hooks from lingering and causing unexpected behavior or conflicts.",
    "files": [
      "src/install.rs"
    ],
    "tags": "git-hooks cleanup stale-state husky installation"
  },
  {
    "commit_sha": "2a52ad7d0fa5217cc538b42e42a02cc969c39da8",
    "category": "decision",
    "title": "Enabling diagnosability by logging hook execution to a persistent file",
    "body": "The decision was made to change hook logging from `/dev/null` to `~/.diwa/hooks.log`. This allows developers to diagnose failures that occur within the git hook context, where stdout/stderr might be suppressed or lost. It shifts the tooling philosophy from 'fire and forget' to observable operations.",
    "files": [
      "src/install.rs"
    ],
    "tags": "logging observability debugging hooks"
  },
  {
    "commit_sha": "2a52ad7d0fa5217cc538b42e42a02cc969c39da8",
    "category": "learning",
    "title": "Re-installation logic must update existing artifacts rather than no-op",
    "body": "The `install_hook` function was previously a no-op if the hook already existed. This was changed to update the script on re-install. The learning here is that 'update' commands must propagate changes to already-installed components; otherwise, users will run outdated logic even after upgrading the main binary.",
    "files": [
      "src/install.rs"
    ],
    "tags": "installation update-strategy propagation lifecycle"
  }
]

[
  {
    "commit_sha": "a90e340d118b2b78216109ee03c189c23f0103f4",
    "category": "decision",
    "title": "Transition from system-level daemons to user-level agents to eliminate sudo dependency",
    "body": "The application was refactored to install Cloudflare Tunnel configurations in ~/Library/LaunchAgents instead of /Library/LaunchDaemons. This architectural shift removes the need for root privileges during installation and management, improving security posture and simplifying the user experience by avoiding password prompts. Log storage was also moved from a global system directory to a user-specific location to align with the new permission model.",
    "files": [
      "src/launchd.rs"
    ],
    "tags": "macos launchd permissions security no-sudo cloudflare-tunnel"
  }
]

[
  {
    "commit_sha": "83c27346030f935943f27a9be9d2e3b0e75b2f03",
    "category": "architecture",
    "title": "Transitioning from single-account to multi-account Cloudflare tunnel synchronization",
    "body": "The system was previously limited to querying tunnels and ingress routes for a single Cloudflare account, which failed in environments where infrastructure is spread across multiple accounts. This change introduces a mechanism to decode all available tunnel tokens to dynamically discover associated account IDs. It then iterates through these accounts, attempting authentication with available API tokens to aggregate ingress routes from all relevant Cloudflare zones.",
    "files": [
      "src/cloudflare.rs",
      "Cargo.toml"
    ],
    "tags": "cloudflare multi-account architecture routing sync"
  }
]

