  {
    "commit_sha": "5f4b49493d5b4635fcb5eb0c3e93b6b8c6f25282",
    "category": "bugfix",
    "title": "Resolve cloudflared path dynamically to support both Intel and Apple Silicon Macs",
    "body": "Hardcoding the cloudflared binary path to `/opt/homebrew` caused silent failures on Intel Macs where Homebrew installs to `/usr/local`. The fix implements a multi-step resolution strategy that checks environment variables, standard Homebrew paths for both architectures, and the system PATH before falling back to a default. This ensures the launchd plist is generated with a valid binary path regardless of the user's hardware architecture.",
    "files": [
      "src/launchd.rs"
    ],
    "tags": "macos launchd homebrew path-resolution apple-silicon intel"
  },
  {
    "commit_sha": "5f4b49493d5b4635fcb5eb0c3e93b6b8c6f25282",
    "category": "pattern",
    "title": "Implement robust process termination with PID snapshotting and timeout-based SIGKILL",
    "body": "The previous stop mechanism returned success immediately after unloading the launchd service, leaving the cloudflared process alive and holding sensitive secrets. The new implementation snapshots the PID before unloading, polls for child exit for 3 seconds, and only sends SIGKILL if the process is still running. This prevents a race condition where the application appears stopped but the underlying tunnel remains active.",
    "files": [
      "src/launchd.rs"
    ],
    "tags": "process-management signal-handling security race-condition launchd"
  },
  {
    "commit_sha": "5f4b49493d5b4635fcb5eb0c3e93b6b8c6f25282",
    "category": "learning",
    "title": "Verify working tree state before bulk-copying files between branches",
    "body": "Version 0.10.0 was released with a bug because the developer copied `launchd.rs` from the main branch without realizing the critical fix existed only in the unstaged working tree, not in the committed history. This highlights the importance of checking `git status` and ensuring all intended changes are committed before performing cross-branch file operations to avoid shipping incomplete features.",
    "files": [
      "src/launchd.rs",
      "Cargo.toml"
    ],
    "tags": "version-control git-workflow release-management process-improvement"
  }
]
